<?php
require_once __DIR__.'/../../config/config.php';require_permission('manage_users');
if(permission_profile()!=='mis')admin_access_denied('MIS account provisioning required.');
require_once __DIR__.'/../../includes/account_provisioning_service.php';require_once __DIR__.'/../../includes/mail.php';
header('Cache-Control: no-store, private');
$pageTitle='Manage Accounts';$service=new AccountProvisioningService(getDB());$error='';$preview=[];$result=null;
if(($_GET['download']??'')==='report'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="student-import-report.csv"');
 $f=fopen('php://output','w');fputcsv($f,['File row','Student ID','Email','Status','Reason'],',','"','');
 foreach($_SESSION['student_import_report']??[] as $row){$cells=[$row['row'],$row['account']['institutional_id'],$row['account']['email'],$row['status'],implode(' ',$row['errors'])];$cells=array_map(static fn($v)=>preg_match('/^[=+@\-\t\r\n]/',(string)$v)?"'".$v:$v,$cells);fputcsv($f,$cells,',','"','');}fclose($f);exit;
}
if(($_GET['download']??'')==='template'){
 if(($_GET['format']??'csv')==='xlsx'){
  require_once __DIR__.'/../../includes/report_export_service.php';$file=ReportExportService::xlsx(['headers'=>AccountProvisioningService::COLUMNS,'rows'=>[]]);try{header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="clinic-account-import-template.xlsx"');readfile($file);}finally{unlink($file);}exit;
 }
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="clinic-account-import-template.csv"');echo "\xEF\xBB\xBF";$f=fopen('php://output','w');fputcsv($f,AccountProvisioningService::COLUMNS,',','"','');fclose($f);exit;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_verify_or_die();
 try{
  $action=$_POST['action']??'';
  if($action==='preview_single'||$action==='preview_csv'){
   unset($_SESSION['account_provision_preview'],$_SESSION['student_import_report']);
   if($action==='preview_csv'){
    $file=$_FILES['accounts_csv']??[];
    if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($file['size']??0)>1048576||!is_string($file['tmp_name']??null)||!is_string($file['name']??null)||!is_uploaded_file($file['tmp_name']))throw new InvalidArgumentException('Upload a UTF-8 CSV or Excel .xlsx file up to 1 MB.');
    $ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));
    if(!in_array($ext,['csv','xlsx'],true))throw new InvalidArgumentException('Choose a CSV or .xlsx workbook.');
    $rows=$ext==='xlsx'?AccountProvisioningService::readXlsx($file['tmp_name']):AccountProvisioningService::readCsv($file['tmp_name']);
   }else{$row=[];foreach(AccountProvisioningService::COLUMNS as $key)$row[$key]=$_POST[$key]??'';$rows=[$row];}
   if($action==='preview_single')foreach($rows as $row)if(!in_array(strtolower(trim($row['role']??'')),['student','teacher'],true))throw new InvalidArgumentException('Choose Student or Teacher. Doctors invite Nurses through Manage Nurses.');
   $preview=$service->preview($rows);if($action==='preview_csv')foreach($preview as &$item){if($item['account']['role']!=='student'){$item['errors'][]='Use Student in the role column.';$item['status']='invalid';}}unset($item);$valid=count(array_filter($preview,static fn($r)=>$r['status']==='ready'))>0;
   if($valid)$_SESSION['account_provision_preview']=['rows'=>array_column($preview,'account'),'bulk'=>$action==='preview_csv','nonce'=>bin2hex(random_bytes(24)),'expires'=>time()+900];
  }elseif($action==='create'){
   $pending=$_SESSION['account_provision_preview']??null;
   if(!$pending||$pending['expires']<time()||!is_string($_POST['nonce']??null)||!hash_equals($pending['nonce'],$_POST['nonce']))throw new InvalidArgumentException('Preview expired or already submitted. Preview the accounts again.');
   unset($_SESSION['account_provision_preview']);if($pending['bulk']??false){$_SESSION['student_import_report']=$service->importStudents((int)current_user()['id'],$pending['rows']);$result=[];}else $result=$service->create((int)current_user()['id'],$pending['rows']);
  }elseif($action==='resend'){
   $id=filter_var($_POST['user_id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1)throw new InvalidArgumentException('Enter a valid pending account ID.');
   $result=[['user_id'=>$id,'delivery_status'=>$service->resend((int)current_user()['id'],$id)]];
  }else throw new InvalidArgumentException('Choose an account setup action.');
 }catch(InvalidArgumentException|RuntimeException $e){http_response_code($e instanceof PDOException?503:422);if(!$e instanceof InvalidArgumentException)error_log('Account setup failed: '.get_class($e).' code='.$e->getCode());$error=$e instanceof InvalidArgumentException?$e->getMessage():'Account setup is temporarily unavailable. Please try again or contact support.';}
}
?>
<!doctype html><html lang="en"><head><?php include __DIR__.'/../../includes/head.php'; ?></head><body><div class="app-wrapper"><?php include __DIR__.'/../../components/sidebar.php'; ?><div class="main-content"><?php include __DIR__.'/../../components/navbar.php'; ?><main class="content-area" id="mainContent"><h1 class="h4">Manage Accounts</h1><p>Create Student or Teacher accounts, or import students from a file. Each recipient receives a secure email link to set up their account within 24 hours.</p>
<?php if(isset($_SESSION['student_import_report'])): $counts=array_count_values(array_column($_SESSION['student_import_report'],'status')); ?><section class="card p-3 mb-3" role="status"><h2 class="h6">Student import summary</h2><p>Successful: <?=(int)($counts['successful']??0)?>. Skipped: <?=(int)($counts['skipped']??0)?>. Failed: <?=(int)($counts['failed']??0)?>.</p><p>Accounts remain pending until setup is complete. Check email delivery below; resend any failed invitations.</p><?php foreach($_SESSION['student_import_report'] as $entry): if($entry['status']!=='successful')continue; ?><p class="small mb-1">File row <?=(int)$entry['row']?>: <?=e(['sent'=>'Email sent','failed'=>'Email failed; resend required','pending'=>'Email status unavailable'][$entry['delivery_status']])?></p><?php endforeach; ?><a href="?download=report">Download import report and correction reasons</a></section><?php endif; ?>
<?php if($error): ?><div class="alert alert-danger" role="alert"><?=e($error)?></div><?php endif; ?>
<?php if($result): $deliveryCounts=array_count_values(array_column($result,'delivery_status')); ?><section class="card p-3 mb-3"><h2 class="h6">Import / invitation summary</h2><p><?=count($result)?> account invitation(s) processed. Email sent: <?=(int)($deliveryCounts['sent']??0)?>. Sending failed: <?=(int)($deliveryCounts['failed']??0)?>. Status unavailable: <?=(int)($deliveryCounts['pending']??0)?>. Email acceptance does not confirm receipt. Failed delivery leaves the account pending; use resend after checking the email settings.</p><ul><?php foreach($result as $row): ?><li>Account #<?=(int)$row['user_id']?> — <?=e(['sent'=>'Email sent','failed'=>'Sending failed','pending'=>'Sending status unavailable'][$row['delivery_status']]??'Sending status unavailable')?></li><?php endforeach; ?></ul></section><?php endif; ?>
<?php if($preview): $previewCounts=array_count_values(array_column($preview,'status')); ?><section class="card p-3 mb-3"><h2 class="h6">Review before creating accounts</h2><p role="status">Ready: <?=(int)($previewCounts['ready']??0)?>. Invalid: <?=(int)($previewCounts['invalid']??0)?>. Duplicates: <?=(int)($previewCounts['duplicate']??0)?>. No accounts have been created yet. Records with errors will be skipped; correct them and upload again.</p><div class="table-responsive" tabindex="0" aria-label="Student import preview"><table class="table"><thead><tr><th>File row</th><th>Identity</th><th>Role / institutional ID</th><th>Email</th><th>Status</th><th>Validation</th></tr></thead><tbody><?php foreach($preview as $row):$p=$row['account']; ?><tr class="<?=$row['status']==='ready'?'table-success':'table-warning'?>"><td><?=$row['row']?></td><td><?=e($p['first_name'].' '.$p['last_name'].' / '.$p['username'])?></td><td><?=e($p['role'].' / '.$p['institutional_id'])?></td><td><?=e($p['email'])?></td><td><?=e(ucfirst($row['status']))?></td><td><?=e($row['errors']?implode(' ',$row['errors']):'Ready')?></td></tr><?php endforeach; ?></tbody></table></div><?php if(isset($_SESSION['account_provision_preview'])): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="create"><input type="hidden" name="nonce" value="<?=e($_SESSION['account_provision_preview']['nonce'])?>"><button class="btn btn-success">Confirm: import valid records and send setup emails</button></form><?php else: ?><p class="text-danger">Correct the errors and preview again. No accounts were created.</p><?php endif; ?></section><?php endif; ?>
<section class="card p-3 mb-3"><h2 class="h6">Single account</h2><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="preview_single"><div class="col-12 col-md-4"><label class="form-label" for="provision-role">Role</label><select class="form-select" name="role" id="provision-role"><?php foreach(['student','teacher'] as $role): ?><option value="<?=$role?>"><?=ucfirst($role)?></option><?php endforeach; ?></select></div>
<?php foreach(['first_name'=>'First name','last_name'=>'Last name','username'=>'Username','institutional_id'=>'Official institutional ID','email'=>'Official email'] as $key=>$label): ?><div class="col-12 col-md-4"><label class="form-label" for="provision-<?=$key?>"><?=$label?></label><input class="form-control" id="provision-<?=$key?>" name="<?=$key?>" type="<?=$key==='email'?'email':'text'?>" maxlength="<?=$key==='email'?120:($key==='username'?50:($key==='institutional_id'?30:80))?>" required <?=$key==='email'?'aria-describedby="provision-email-state"':''?>><?php if($key==='email'): ?><small id="provision-email-state" role="status" aria-live="polite"></small><?php endif; ?></div><?php endforeach; ?><div class="col-12"><button class="btn btn-outline-success">Validate and preview account</button></div></form></section>
